using System;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Web.Script.Serialization;

// A single serialized WinUSB data session. No firmware/updater SDK is loaded.
sealed class NamDataSession {
 readonly SemaphoreSlim gate=new SemaphoreSlim(1,1);readonly string records;readonly Action<string> log;readonly Func<string,Action<string>,PodWireSession> factory;PodWireSession wire;PodIrSlot[] slots;bool closed,ready;int operation;
 public NamDeviceState State;public readonly NamCatalog Catalog;public bool Connected{get{return ready&&!closed;}}
 public NamDataSession(string folder,Action<string> logger,Func<string,Action<string>,PodWireSession> transportFactory=null){records=folder;log=logger;factory=transportFactory??((path,output)=>new PodWireSession(path,output));Directory.CreateDirectory(records);Catalog=new NamCatalog(transportFactory==null?null:Path.Combine(records,"fixture-library.json"));}
 void OpenWire(){if(wire!=null)throw new IOException("Hay una operación USB pendiente");wire=factory(Path.Combine(records,"wire-"+(++operation).ToString("0000")),log);wire.Handshake();}
 void CloseWire(){if(wire==null)return;var old=wire;wire=null;old.Dispose();}
 async Task<T> Run<T>(Func<T> action){await gate.WaitAsync();try{return await Task.Run(()=>{using(StudioUsbGate.Acquire("Biblioteca NAM")){try{return action();}catch{ready=false;throw;}finally{CloseWire();}}});}finally{gate.Release();}}
 public Task<NamDeviceState> Connect(){return Run(()=>{closed=false;var result=ReadBank();ready=true;return result;});}
 NamDeviceState ReadBank(){try{OpenWire();return RefreshInside();}finally{CloseWire();}}
 NamDeviceState RefreshInside(){slots=wire.ScanIr().Select(PodIrSlot.From).ToArray();if(slots.Length!=128||slots.Select(s=>s.Index).Distinct().Count()!=128)throw new IOException("Banco incompleto");State=new NamDeviceState{Name="POD Go",Version="P34",Bank=slots,Names=slots.Select(s=>s.Used?(s.Name.Length==0?"(sin nombre)":s.Name):"").ToArray()};File.WriteAllText(Path.Combine(records,"ir-bank-latest.json"),new JavaScriptSerializer().Serialize(slots));return State;}
 public Task<NamDeviceState> Refresh(){return Run(ReadBank);}
 public Task<string> Inspect(){return Run(()=>{File.WriteAllText(Path.Combine(records,"connection.json"),new JavaScriptSerializer().Serialize(new{identity="0e41:4247 / P34",user_ir_slots=slots.Length,used=slots.Count(s=>s.Used),free=slots.Count(s=>!s.Used),firmware_written=false,presets_changed=false}));return records;});}
 public Task<string> Send(NamCapture selected,int destination=-1,bool replaceNam=false,PodIrSlot expectedDestination=null,string shortName=null){return Run(()=>{
   if(!Connected)throw new IOException("POD Go desconectada");var capture=NamCapture.Read(selected.Source,selected.OutputDb,selected.InputDb);if(capture.Hash!=selected.Hash)throw new IOException("El NAM cambió tras validarlo");byte[] payload=NamCapture.AudioPayload(capture.Wave);string dataHash=NamCapture.Sha(payload),deviceName=NamTitle.DeviceName(dataHash,shortName??NamTitle.Suggest(capture.Name));
   ReadBank();var before=slots.ToArray();var cached=before.FirstOrDefault(s=>s.Used&&s.Name==deviceName&&(destination<0||s.Index==destination));if(cached!=null){byte[] existing;try{OpenWire();existing=wire.ExportIr(cached.Index);}finally{CloseWire();}if(existing.SequenceEqual(payload)){Catalog.Remember(capture,dataHash);log("NAM ya conservado y verificado · Model "+(cached.Index+1));return "Model "+(cached.Index+1)+": ya contiene este NAM y nivel; verificado.";}}
   int slot=destination<0?NamGuards.FreeSlot(State.Names):destination;if(slot<0||slot>=128)throw new IOException("Elige un destino entre Model 1 y 128");var target=before.Single(s=>s.Index==slot);if(expectedDestination!=null&&!NamGuards.SameSlot(target,expectedDestination))throw new IOException("El destino cambió desde la consulta. Actualiza la biblioteca y revísalo.");if(target.Used&&(!replaceNam||!NamCatalog.ManagedName(target.Name)))throw new IOException("Model "+(slot+1)+" contiene "+target.Name+". Los IR de pantalla están protegidos.");
   string folder=Path.Combine(records,"NAM-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fff"));Directory.CreateDirectory(folder);var json=new JavaScriptSerializer();File.WriteAllText(Path.Combine(folder,"bank-before.json"),json.Serialize(before));File.Copy(capture.Source,Path.Combine(folder,"source.nam"));File.WriteAllBytes(Path.Combine(folder,"carrier.wav"),capture.Wave);
   if(target.Used){byte[] previous;try{OpenWire();previous=wire.ExportIr(slot);}finally{CloseWire();}string previousHash=NamCapture.Sha(previous);if(!NamCatalog.ValidCarrier(previous)||!previousHash.StartsWith(target.Name.Substring(4,12),StringComparison.OrdinalIgnoreCase))throw new IOException("El contenido de destino no es un NAM gestionado verificable; se conserva.");File.WriteAllBytes(Path.Combine(folder,"previous.float32.bin"),previous);File.WriteAllText(Path.Combine(folder,"previous.json"),json.Serialize(new{slot=slot,Model=slot+1,metadata=target,payload_sha256=previousHash}));log("Copia previa verificada de Model "+(slot+1)+" conservada en "+folder);}
   log((target.Used?"Actualizar ":"Cargar ")+capture.Name+" → Model "+(slot+1)+" · salida "+capture.OutputDb.ToString("0.0")+" dB");var started=DateTime.UtcNow;byte[] returned;try{OpenWire();wire.UploadStore(slot,deviceName,payload,target.Used?target:null);}finally{CloseWire();}try{OpenWire();returned=wire.ExportIr(slot);}finally{CloseWire();}if(!returned.SequenceEqual(payload))throw new IOException("El retorno NAM difiere del modelo enviado");File.WriteAllBytes(Path.Combine(folder,"readback.float32.bin"),returned);ReadBank();
   foreach(var old in before.Where(s=>s.Index!=slot)){var now=slots.Single(s=>s.Index==old.Index);if(old.Used!=now.Used||old.Name!=now.Name||old.Samples!=now.Samples||old.Checksum!=now.Checksum)throw new IOException("Otra posición cambió durante la sesión; consulta el registro");}
   var report=new{source_name=capture.Name,device_name=deviceName,display_title=NamTitle.Preview(slot+1,deviceName.Substring(17)),source_sha256=capture.Hash,payload_sha256=dataHash,input_gain_db=capture.InputDb,output_gain_db=capture.OutputDb,slot_index=slot,Model=slot+1,replaced_existing_NAM=target.Used,previous_backup=target.Used?folder:null,readback_byte_exact=true,other_slots_metadata_unchanged=true,elapsed_seconds=(DateTime.UtcNow-started).TotalSeconds,firmware_written=false,presets_changed=false,power_cycle_persistence_verified=false};File.WriteAllText(Path.Combine(folder,"verified.json"),json.Serialize(report));Catalog.Remember(capture,dataHash);log("NAM enviado y leído íntegro · Model "+(slot+1)+" · salida "+capture.OutputDb.ToString("0.0")+" dB");return "Model "+(slot+1)+" verificado · "+capture.OutputDb.ToString("0.0")+" dB. "+(target.Used?"Selecciona otro Model y vuelve a éste para recargarlo.":"Selecciónalo en la POD Go para escucharlo.");
  });}
 public Task<bool> Disconnect(){return Run(()=>{CloseWire();closed=true;ready=false;return true;});}
}
